/bin/bash -lc "python - <<'PY'
from sim import Sim
import numpy as np
sim=Sim(); h=sim.home_ctrl()

# settle to quasi-stand for short time
for _ in range(50):
    sim.data.ctrl[:] = h
    sim.step(1)
base=sim.pelvis_position().copy()
print('base pelvis',base)

# coarse scan right arm controls for min elbow distance to touch point
best=(1e9,None,None)
for sp in np.linspace(-1.5,1.5,13):
  for sr in np.linspace(-1.5,1.5,13):
    for sy in np.linspace(-1.5,1.5,13):
      for e in np.linspace(-1.5,1.5,13):
        sim2=Sim();
        c=sim2.home_ctrl();
        c[15]=sp; c[16]=sr; c[17]=sy; c[18]=e
        # keep stable short
        for _ in range(80):
          sim2.data.ctrl[:] = c
          sim2.step(1)
        d=sim2.distance_to_touch()
        if d<best[0]:
          best=(d,(sp,sr,sy,e),sim2.elbow_positions()['right'].copy(),sim2.pelvis_position().copy())
print('best',best[0],'params',best[1],'right_elbow',best[2],'pelvis',best[3])
PY"
